    add(L("ग्रह-विश्लेषण: सूर्य, चंद्र, मंगल", "Planet analysis: Sun, Moon, Mars"), ["Sun", "Moon", "Mars"].map(planetCard).join(""), det);
    add(L("ग्रह-विश्लेषण: बुध, गुरु, शुक्र", "Planet analysis: Mercury, Jupiter, Venus"), ["Mercury", "Jupiter", "Venus"].map(planetCard).join(""), det);
