    if (marsOnLagna) weak.push([L("गुस्सा", "Anger"), L("मंगल का लग्न से संबंध — गुस्सा जल्दी आता है, हालाँकि उतनी ही जल्दी उतर भी जाता है।", "Mars linked to the ascendant — anger rises fast, though it fades fast too.")]);
